'use strict';
/* Bundles authored JSON into js/data/content-bundle.js so the app runs from a plain
 * <script> tag (works on GitHub Pages and from file:// on locked-down school devices).
 * Source of truth stays in /content; never edit the bundle by hand. */
const fs = require('fs');
const path = require('path');
const { loadContent } = require('./load-library.js');

const content = loadContent();
const out = '/* GENERATED by tools/build-bundle.js from /content. Do not edit by hand. */\n' +
  '(function (root) { root.WRG = root.WRG || {}; root.WRG.content = ' + JSON.stringify(content) + '; }(typeof self !== "undefined" ? self : this));\n';
const target = path.join(__dirname, '..', 'js', 'data', 'content-bundle.js');
fs.writeFileSync(target, out);
console.log('Wrote ' + path.relative(process.cwd(), target) + ' (' + out.length + ' bytes, ' + content.templates.length + ' templates)');

// Compositional generator content (frameworks, typed slot pools, kits) -> js/data/compose-bundle.js
const { loadCompose } = require('./compose-load.js');
const K = require('../js/compose/check.js');
const library = require('../js/core/library.js');
const cx = loadCompose();
const kv = K.validateCompose(library.create(content), cx);
if (!kv.ok) { console.error('Compose content has errors:\n  ' + kv.errors.slice(0, 20).join('\n  ')); process.exit(1); }
const cxOut = '/* GENERATED by tools/build-bundle.js from /content/compose. Do not edit by hand. */\n' +
  '(function (root) { root.WRG = root.WRG || {}; root.WRG.composeContent = ' + JSON.stringify(cx) + '; }(typeof self !== "undefined" ? self : this));\n';
const cxTarget = path.join(__dirname, '..', 'js', 'data', 'compose-bundle.js');
fs.writeFileSync(cxTarget, cxOut);
console.log('Wrote ' + path.relative(process.cwd(), cxTarget) + ' (' + cxOut.length + ' bytes, ' + cx.kits.length + ' kits)');
